@RestController
public class LdapUserController {
    @Autowired
    private LdapTemplate ldapTemplate;

    @GetMapping("/find_user")
    public List<String> findUser(@RequestParam String uid) {
        // 使用 AND filterContainers 容器 + 编码值，避免拼接
